-- 30,000 pre-played rounds of על האש בכינרת (engine docs/vendor/kin_engine.js). The server picks one at random;
-- the browser replays the same seed. Mean of this table = the game's exact return.
create table if not exists kin_seeds (id int primary key, seed bigint not null, total numeric not null);
alter table kin_seeds enable row level security; revoke all on kin_seeds from anon, authenticated;
truncate kin_seeds;
